INSERT INTO blog (title, summary, content, published_date, thumbnail_url) VALUES
('Building REST APIs with Spring Boot', 'A practical overview of clean REST API design with Spring Boot.', 'Spring Boot makes it straightforward to build maintainable REST APIs. Start with resource-focused controllers, move business rules into services, and keep persistence concerns inside repositories. Validate incoming data at the boundary and return consistent error responses.', '2026-08-20', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=1200&q=80'),
('Spring Data JPA: From Entity to Repository', 'How JPA entities and repositories simplify database access in Java applications.', 'Spring Data JPA removes much of the repetitive persistence code. Define an entity that models your table, create a JpaRepository, and let Spring generate common CRUD operations. As the project grows, put domain logic in services and keep controllers thin.', '2026-09-05', 'https://images.unsplash.com/photo-1461749280684-dccba630e2f6?auto=format&fit=crop&w=1200&q=80');
